const dns = require('dns');
const crypto = require('crypto');
const { EventEmitter } = require('events');

// Shared, conservative domain validator (unrelated-fix: input validation)
function isValidDomain(domain) {
  if (typeof domain !== 'string') return false;
  if (domain.length === 0 || domain.length > 253) return false;
  // Basic hostname format: labels of alphanumerics/hyphens separated by dots
  return /^(?=.{1,253}$)(?!-)([A-Za-z0-9-]{1,63}(?<!-)\.)+[A-Za-z]{2,63}$/.test(domain);
}

class DNSResolverService extends EventEmitter {
  constructor() {
    super();
    this.cache = new Map();
    this.pendingRequests = new Map();
    this.userQuotas = new Map();
    this.MAX_CONCURRENT = 10;
    this.QUOTA_LIMIT = 100;
  }

  _generateRequestId(userId, domain) {
    return crypto.createHash('sha256')
      .update(`${userId}:${domain}:${Date.now()}`)
      .digest('hex').slice(0, 16);
  }

  _getUserContext(userId) {
    if (!this.userQuotas.has(userId)) {
      this.userQuotas.set(userId, { count: 0, results: new Map() });
    }
    return this.userQuotas.get(userId);
  }

  async _performLookup(requestId, domain, recordType) {
    return new Promise((resolve, reject) => {
      const resolver = new dns.Resolver();
      resolver.setServers(['8.8.8.8', '8.8.4.4']);

      const method = recordType === 'A' ? 'resolve4' : 
                     recordType === 'AAAA' ? 'resolve6' :
                     recordType === 'MX' ? 'resolveMx' :
                     recordType === 'TXT' ? 'resolveTxt' : 'resolve4';

      resolver[method](domain, (err, addresses) => {
        if (err) {
          reject({ requestId, error: err.code || 'UNKNOWN_ERROR' });
        } else {
          resolve({ requestId, domain, recordType, addresses, timestamp: Date.now() });
        }
      });
    });
  }

  async resolveForUser(userId, domain, recordType = 'A') {
    // Unrelated-fix: validate domain at the service boundary so all callers
    // (including batchResolve) are protected.
    if (!isValidDomain(domain)) {
      throw new Error('INVALID_DOMAIN');
    }

    const ctx = this._getUserContext(userId);

    if (ctx.count >= this.QUOTA_LIMIT) {
      throw new Error('QUOTA_EXCEEDED');
    }

    const requestId = this._generateRequestId(userId, domain);
    const cacheKey = `${domain}:${recordType}`;

    if (this.cache.has(cacheKey)) {
      const cached = this.cache.get(cacheKey);
      if (Date.now() - cached.timestamp < 300000) {
        ctx.results.set(requestId, cached);
        return { requestId, ...cached };
      }
    }

    this.pendingRequests.set(requestId, { userId, domain, recordType, status: 'pending' });
    ctx.count++;

    try {
      const result = await this._performLookup(requestId, domain, recordType);
      this.cache.set(cacheKey, result);
      ctx.results.set(requestId, result);
      this.pendingRequests.delete(requestId);
      this.emit('resolved', { userId, requestId, result });
      return { requestId, ...result };
    } catch (error) {
      this.pendingRequests.delete(requestId);
      throw error;
    }
  }

  async getResult(userId, requestId) {
    const pending = this.pendingRequests.get(requestId);
    if (pending) {
      if (pending.userId !== userId) {
        return { status: 'not_found', requestId };
      }
      return { status: 'pending', requestId };
    }

    // Authorization check: only return results owned by the requesting user
    const ctx = this._getUserContext(userId);
    if (ctx.results.has(requestId)) {
      return { status: 'complete', ...ctx.results.get(requestId) };
    }

    return { status: 'not_found', requestId };
  }

  async batchResolve(userId, domains, recordType = 'A') {
    const results = [];
    const chunks = [];

    for (let i = 0; i < domains.length; i += this.MAX_CONCURRENT) {
      chunks.push(domains.slice(i, i + this.MAX_CONCURRENT));
    }

    for (const chunk of chunks) {
      const chunkResults = await Promise.allSettled(
        chunk.map(domain => this.resolveForUser(userId, domain, recordType))
      );
      results.push(...chunkResults);
    }

    return results.map(r => r.status === 'fulfilled' ? r.value : { error: r.reason });
  }

  getUserHistory(userId) {
    const ctx = this._getUserContext(userId);
    return Array.from(ctx.results.entries()).map(([id, result]) => ({
      requestId: id,
      domain: result.domain,
      recordType: result.recordType,
      timestamp: result.timestamp
    }));
  }
}

// Express route handlers
const express = require('express');
const app = express();
app.use(express.json());

const resolverService = new DNSResolverService();

function authenticateUser(req, res, next) {
  const authHeader = req.headers['x-user-id'];
  if (!authHeader) {
    return res.status(401).json({ error: 'Authentication required' });
  }
  req.userId = authHeader;
  next();
}

app.use(authenticateUser);

app.post('/api/resolve', async (req, res) => {
  try {
    const { domain, recordType } = req.body;
    if (!domain || typeof domain !== 'string' || !isValidDomain(domain)) {
      return res.status(400).json({ error: 'Invalid domain' });
    }
    const result = await resolverService.resolveForUser(req.userId, domain, recordType);
    res.json(result);
  } catch (err) {
    const code = err.message === 'QUOTA_EXCEEDED' ? 429
      : err.message === 'INVALID_DOMAIN' ? 400 : 500;
    res.status(code).json({ error: err.message });
  }
});

app.get('/api/result/:requestId', async (req, res) => {
  const result = await resolverService.getResult(req.userId, req.params.requestId);
  res.json(result);
});

app.get('/api/history', (req, res) => {
  res.json(resolverService.getUserHistory(req.userId));
});

app.post('/api/batch', async (req, res) => {
  try {
    const { domains, recordType } = req.body;
    if (!Array.isArray(domains) || domains.length > 50) {
      return res.status(400).json({ error: 'Invalid domains list' });
    }
    // Unrelated-fix: validate each entry before processing the batch.
    if (!domains.every(isValidDomain)) {
      return res.status(400).json({ error: 'Invalid domain in list' });
    }
    const results = await resolverService.batchResolve(req.userId, domains, recordType);
    res.json(results);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

module.exports = { app, resolverService, DNSResolverService };
